// pay.bynk
context pay

exports opaque { Status }        // the owner hides the shape

type Status = | Paid | Declined

// shop.bynk
context shop

consumes pay

service checkout {
    on call() -> Effect[Bool] by Caller {
        let s <- pay.charge(1)
        match s {                      // ✗ `Status` is opaque here, so its variants are hidden
            Paid => Effect.pure(true)
            Declined => Effect.pure(false)
        }
    }
}

